+func renderPerformanceReport(targets []PerformanceTarget, baseline []PerformanceMeasurement, result PerformanceResult) string {
+	var b strings.Builder
+	fmt.Fprintf(&b, "# Performance verification\n\nStatus: `%s`\n\n## Targets\n\n| ID | Scenario | Metric | Contract | Baseline | Candidate | Outcome |\n| --- | --- | --- | --- | ---: | ---: | --- |\n", result.Outcome)
+	baseByID := map[string]string{}
+	for _, measurement := range baseline {
+		baseByID[measurement.Target.ID] = measurement.Qualification.Median
+	}
+	comparisonByID := map[string]PerformanceComparison{}
+	for _, comparison := range result.Comparisons {
+		comparisonByID[comparison.TargetID] = comparison
+	}
+	for _, target := range targets {
+		comparison := comparisonByID[target.ID]
+		fmt.Fprintf(&b, "| %s | %s | %s | %s %s %s | %s | %s | %s |\n", target.ID, escapePerformanceCell(target.Scenario), escapePerformanceCell(target.Metric), target.Comparator, target.Value, target.Unit, baseByID[target.ID], comparison.Candidate, comparison.Outcome)
+	}
+	fmt.Fprintf(&b, "\n## Change summary\n\n")
+	if result.InitialImplementation == result.FinalImplementation {
+		fmt.Fprintln(&b, "No implementation change was promoted in this attempt.")
+	} else {
+		fmt.Fprintf(&b, "A contained optimization was promoted from `%s` to `%s`.\n", result.InitialImplementation, result.FinalImplementation)
+	}
+	b.WriteString("\n## Qualification\n\n")
+	for _, target := range result.TargetResults {
+		fmt.Fprintf(&b, "- `%s`: baseline qualified=%t, final qualified=%t, final CV=%g%%\n", target.Target.ID, target.BaselineQualification.Qualified, target.FinalQualification.Qualified, target.FinalQualification.CVPercent)
+	}
+	b.WriteString("\n## Blockers\n\n")
+	if result.Outcome == PerformanceBlocked || result.Outcome == PerformanceCleanupUncertain {
+		fmt.Fprintln(&b, "The retained result records a blocking authority or cleanup failure.")
+	} else {
+		fmt.Fprintln(&b, "None.")
+	}
+	fmt.Fprintf(&b, "\n## Evidence\n\n- Target packet: `%s`\n- Benchmark manifest: `%s`\n- Environment: `%s`\n- Baseline: `%s`\n- Final: `%s`\n- Commands: `%d`\n- Runtime attempts: `%d`\n\n## Next action\n\n%s\n", result.Packet.Path, result.Manifest.Path, result.Environment.Path, result.Baseline.Path, result.Final.Path, result.Counters.Commands, result.Counters.RuntimeAttempts, result.NextAction)
+	return b.String()
+}
+
+func escapePerformanceCell(value string) string {
+	value = strings.ReplaceAll(value, "|", "\\|")
+	return strings.ReplaceAll(strings.ReplaceAll(value, "\r", " "), "\n", " ")
+}
+
+func (store PerformanceStore) readResult(ref PerformanceArtifactRef) (PerformanceResult, error) {
+	path, err := store.resolve(ref.Path)
+	if err != nil {
+		return PerformanceResult{}, err
+	}
+	data, err := os.ReadFile(path)
+	if err != nil {
+		return PerformanceResult{}, err
+	}
+	if hashBytes(data) != ref.Digest {
+		return PerformanceResult{}, fmt.Errorf("performance result digest mismatch")
+	}
+	var result PerformanceResult
+	decoder := jsonNewStrictDecoder(data)
+	if err := decoder(&result); err != nil {
+		return PerformanceResult{}, err
+	}
+	return result, nil
+}
+
+func jsonNewStrictDecoder(data []byte) func(any) error {
+	return func(target any) error {
+		decoder := json.NewDecoder(strings.NewReader(string(data)))
+		decoder.DisallowUnknownFields()
+		if err := decoder.Decode(target); err != nil {
+			return err
+		}
+		if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
+			return fmt.Errorf("trailing JSON data")
+		}
+		return nil
+	}
+}

