+var errImmutableRecordConflict = errors.New("immutable record conflict")
+
+func privateImmutableWrite(path string, data []byte, kind string, hooks QAStateHooks) error {
+	dir := filepath.Dir(path)
+	if err := os.MkdirAll(dir, 0o700); err != nil {
+		return err
+	}
+	if pathHasComponent(path, "verification") {
+		for current := dir; ; current = filepath.Dir(current) {
+			if err := os.Chmod(current, 0o700); err != nil {
+				return err
+			}
+			if filepath.Base(current) == "verification" {
+				break
+			}
+			parent := filepath.Dir(current)
+			if parent == current {
+				return fmt.Errorf("verification directory not found")
+			}
+		}
+	}
+	temp, err := os.CreateTemp(dir, ".qa-"+kind+"-*.tmp")
+	if err != nil {
+		return err
+	}
+	tempPath := temp.Name()
+	defer os.Remove(tempPath)
+	if err := temp.Chmod(0o600); err != nil {
+		_ = temp.Close()
+		return err
+	}
+	if _, err := temp.Write(data); err != nil {
+		_ = temp.Close()
+		return err
+	}
+	if err := temp.Sync(); err != nil {
+		_ = temp.Close()
+		return err
+	}
+	if err := temp.Close(); err != nil {
+		return err
+	}
+	if hooks.BeforeRename != nil {
+		if err := hooks.BeforeRename(kind, path); err != nil {
+			return err
+		}
+	}
+	if err := os.Link(tempPath, path); err != nil {
+		if errors.Is(err, fs.ErrExist) {
+			current, readErr := os.ReadFile(path)
+			if readErr == nil && bytes.Equal(current, data) {
+				return nil
+			}
+			if readErr == nil {
+				return errImmutableRecordConflict
+			}
+			return readErr
+		}
+		return err
+	}
+	syncDir(dir)
+	return nil
+}
