+func validatePerformanceFlowSummary(root string, s Sprint, summary PerformanceFlowSummary, path string) error {
+	switch summary.Phase {
+	case PerformancePhaseReady, PerformancePhasePreparing, PerformancePhaseBaseline, PerformancePhaseOptimizing, PerformancePhaseFinalizing, PerformancePhaseTerminal, PerformancePhaseStale:
+	default:
+		return fmt.Errorf("%w: %s: invalid performance phase", ErrFlowStateMalformed, path)
+	}
+	if summary.Required < 0 || summary.Reports < 0 || summary.Met < 0 || summary.Missed < 0 || summary.Met+summary.Missed > summary.Required {
+		return fmt.Errorf("%w: %s: invalid performance counts", ErrFlowStateMalformed, path)
+	}
+	if summary.StatePath == "" || !validFingerprint(summary.StateDigest) || strings.TrimSpace(summary.NextAction) == "" {
+		return fmt.Errorf("%w: %s: incomplete performance summary pointer", ErrFlowStateMalformed, path)
+	}
+	resolved, err := resolveSprintContained(root, s, summary.StatePath)
+	if err != nil || filepath.Base(resolved) != "performance-state.json" || filepath.Base(filepath.Dir(resolved)) != "verification" {
+		return fmt.Errorf("%w: %s: unsafe performance summary pointer", ErrFlowStateMalformed, path)
+	}
 	return nil
 }
